import os
import torch
import numpy as np


class Config:
    """
    Configuration class for the Scalar Coupling Prediction project.
    Handles file paths, data processing parameters, model hyperparameters,
    and training settings.
    """

    # ==========================================
    # 1. File Paths
    # ==========================================
    # Base Directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_12"
    SUBMISSION_DIR = "./submission"

    # Metadata Paths (Generated by previous steps)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Raw Data Paths
    STRUCTURES_CSV = os.path.join(INPUT_DIR, "structures.csv")
    STRUCTURES_DIR = os.path.join(INPUT_DIR, "structures")
    DIPOLE_MOMENTS_PATH = os.path.join(INPUT_DIR, "dipole_moments.csv")
    MAGNETIC_SHIELDING_PATH = os.path.join(INPUT_DIR, "magnetic_shielding_tensors.csv")
    MULLIKEN_CHARGES_PATH = os.path.join(INPUT_DIR, "mulliken_charges.csv")
    POTENTIAL_ENERGY_PATH = os.path.join(INPUT_DIR, "potential_energy.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Paths
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Cache Paths (for Flattened SoA Data)
    CACHE_DIR = WORKING_DIR
    STATS_PATH = os.path.join(CACHE_DIR, "stats.npy")

    # ==========================================
    # 2. Data Processing Parameters
    # ==========================================
    # Atom Mapping (Element Symbol -> Embedding Index)
    ATOM_MAP = {"H": 0, "C": 1, "N": 2, "O": 3, "F": 4}
    NUM_ATOM_TYPES = len(ATOM_MAP)

    # Coupling Type Mapping (Type -> Index)
    # Sorted alphabetically to ensure consistency
    COUPLING_TYPES = sorted(
        ["1JHC", "2JHH", "1JHN", "2JHN", "2JHC", "3JHH", "3JHC", "3JHN"]
    )
    COUPLING_MAP = {t: i for i, t in enumerate(COUPLING_TYPES)}
    NUM_COUPLING_TYPES = len(COUPLING_TYPES)

    # Graph Construction
    CUTOFF = 5.0  # Angstroms (Radius for neighbor search)
    MAX_NEIGHBORS = 32  # Maximum neighbors per atom to consider for efficiency

    # ==========================================
    # 3. Model Hyperparameters
    # ==========================================
    # Architecture: Directional Message Passing with Continuous Filters
    HIDDEN_DIM = 192  # Dimension of node/edge embeddings
    NUM_LAYERS = 6  # Number of message passing layers
    NUM_RBF = 64  # Number of Radial Basis Functions for edge length
    NUM_ANGLE_RBF = 32  # Number of RBFs for bond angles
    DROPOUT = 0.1  # Dropout rate

    # Readout
    USE_AUXILIARY_HEADS = True  # Whether to predict shielding/charges

    # ==========================================
    # 4. Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 128  # Batch size (number of molecules)
    LEARNING_RATE = 5e-4  # Initial learning rate
    WEIGHT_DECAY = 1e-6  # L2 regularization
    MAX_EPOCHS = 40  # Maximum training epochs
    PATIENCE = 5  # Early stopping patience

    # Loss Weights
    # Total Loss = L_coupling + LAMBDA * (L_shielding + L_charges)
    AUX_LOSS_WEIGHT = 0.1

    # Hardware
    NUM_WORKERS = 4  # Data loading workers
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    def __init__(self):
        """Initialize configuration and create necessary directories."""
        # Create working and submission directories
        os.makedirs(self.WORKING_DIR, exist_ok=True)
        os.makedirs(self.SUBMISSION_DIR, exist_ok=True)

        # Set random seeds for reproducibility
        self._set_seed(self.SEED)

    def _set_seed(self, seed):
        """Sets random seeds for Python, NumPy, and PyTorch."""
        import random

        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed(seed)
            torch.cuda.manual_seed_all(seed)
            # Ensure deterministic behavior for CuDNN
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False

    def get_coupling_type_index(self, coupling_type):
        """Returns the integer index for a given coupling type string."""
        return self.COUPLING_MAP.get(coupling_type, -1)

    def get_atom_index(self, atom_symbol):
        """Returns the integer index for a given atom symbol."""
        return self.ATOM_MAP.get(atom_symbol, -1)
